// 无未知写者兜底；批次数量、Owner、预约、容量和原revision一起检查，普通世界不启用这些纯口。
#include "growth_market_resource_contract.hpp"
#include <algorithm>
#include <charconv>
#include <map>
#include <set>
#include <type_traits>
namespace hanmo::resident {namespace {
// 完整读戳必须同一个候选，不能捕获旧World或跨执行epoch使用许可。
bool same_identity(const WorldIdentity& a,const WorldIdentity& b){return a.world_id==b.world_id&&a.execution_epoch==b.execution_epoch&&a.revision==b.revision&&a.tick==b.tick;}
bool leg_equal(const MarketQuantityLeg& a,const MarketQuantityLeg& b){return a.inventory_id==b.inventory_id&&a.item_id==b.item_id&&owner_equal(a.owner,b.owner)&&a.signed_quantity==b.signed_quantity;}
bool same_order(const FieldOrder& a,const FieldOrder& b,const FieldOrder& canonical){return (a.empty()?canonical:a)==(b.empty()?canonical:b);}
bool metadata_equal(const LotView& a,const LotView& b){return a.id==b.id&&a.item_id==b.item_id&&owner_equal(a.owner,b.owner)&&a.reserved_by==b.reserved_by&&!a.extra&&!b.extra&&same_order(a.field_order,b.field_order,{"id","item_id","quantity","owner","reserved_by"});}
Outcome<Integer> lot_ordinal(const StableId& id){if(id.rfind("lot:",0)!=0)return {false,0,common_failure("ProtectedMarketLotIdentityInvalid",id).error};const auto digits=id.substr(4);Integer n=0;auto r=std::from_chars(digits.data(),digits.data()+digits.size(),n);if(r.ec!=std::errc{}||r.ptr!=digits.data()+digits.size()||n<1||std::to_string(n)!=digits)return {false,0,common_failure("ProtectedMarketLotIdentityInvalid",id).error};return {true,n,{}};}
}
Outcome<MarketRecipeInspection> inspect_protected_market_recipe(const CommonStore& c,const ProtectedMarketAccounts& policy,const ResourceRecipe& recipe,const MarketRecipeAuthorization* scope){
    auto fail=[](const StableId& code,const StableId& id=StableId{})->Outcome<MarketRecipeInspection>{return {false,{},common_failure(code,id).error};};if(policy.inventories.empty())return {true,{},{}};
    if(scope&&(!same_identity(c.state().identity,scope->source_identity)||scope->original_business_key.empty()||(scope->kind!=MarketCauseKind::growth_trade&&scope->kind!=MarketCauseKind::local_production&&scope->kind!=MarketCauseKind::local_ration)))return fail("ProtectedMarketScopeInvalid");
    if(scope&&scope->kind==MarketCauseKind::local_production){bool debit=false,credit=false;for(const auto& leg:scope->expected_market_legs){debit=debit||leg.signed_quantity<0;credit=credit||leg.signed_quantity>0;}if(debit&&credit)return fail("ProtectedMarketProductionStagesMixed");}
    MarketRecipeInspection out;std::vector<MarketQuantityLeg> actual;
    auto touch=[&](const StableId& id,const StableId& item,Integer quantity,const Owner& owner,bool add,bool fragmented)->Status{
        const auto* selected=policy.inventories.find(id);if(!selected)return common_success();const auto* current=c.inventory(id);
        if(!scope)return common_failure("ProtectedMarketWriterRequired",id);if(!current||!owner_equal(current->owner,selected->owner)||current->capacity!=selected->capacity||!owner_equal(owner,selected->owner)||item.empty()||quantity==0)return common_failure("ProtectedMarketOperationInvalid",id);
        actual.push_back({id,item,owner,quantity});auto at=std::find_if(out.inventories.begin(),out.inventories.end(),[&](const auto& x){return x.inventory_id==id;});if(at==out.inventories.end()){out.inventories.push_back({id});at=std::prev(out.inventories.end());}at->legs.push_back(actual.back());if(add)++at->add_operations;else ++at->consume_operations;at->fragmented_adds=at->fragmented_adds||fragmented;return common_success();
    };
    for(const auto& operation:recipe.operations){auto checked=std::visit([&](const auto& op)->Status{using T=std::decay_t<decltype(op)>;
        if constexpr(std::is_same_v<T,WalletDelta>||std::is_same_v<T,SetReservation>||std::is_same_v<T,SetWalletOwner>||std::is_same_v<T,CreateWallet>)return common_success();
        else if constexpr(std::is_same_v<T,AddLot>){if(!policy.inventories.find(op.inventory_id))return common_success();if(!scope||scope->kind!=MarketCauseKind::local_production||op.quantity<=0||!op.reservation.empty())return common_failure("ProtectedMarketWriterRequired",op.inventory_id);return touch(op.inventory_id,op.item_id,op.quantity,op.owner,true,false);}
        else if constexpr(std::is_same_v<T,ConsumeLots>){const auto* selected=policy.inventories.find(op.inventory_id);if(!selected)return common_success();if(!scope||(scope->kind!=MarketCauseKind::local_production&&scope->kind!=MarketCauseKind::local_ration)||op.quantity<=0||!op.reservation.empty()||op.owners.size()!=1||!owner_equal(op.owners[0],selected->owner))return common_failure("ProtectedMarketWriterRequired",op.inventory_id);return touch(op.inventory_id,op.item_id,-op.quantity,op.owners[0],false,false);}
        else if constexpr(std::is_same_v<T,TransferLots>){const auto* from=policy.inventories.find(op.source_id);const auto* to=policy.inventories.find(op.destination_id);if(!from&&!to)return common_success();if(op.source_id==op.destination_id)return common_failure("ProtectedMarketSelfTransfer");if(from&&to)return common_failure("ProtectedMarketTradeNotDedicated");if(!scope||scope->kind!=MarketCauseKind::growth_trade||op.quantity<=0||!op.reservation.empty()||op.owners.size()!=1)return common_failure("ProtectedMarketWriterRequired");auto status=touch(op.source_id,op.item_id,-op.quantity,op.owners[0],false,false);if(!status.ok)return status;return touch(op.destination_id,op.item_id,op.quantity,op.new_owner?*op.new_owner:op.owners[0],true,true);}
        else if constexpr(std::is_same_v<T,ReleaseActionResources>||std::is_same_v<T,ReleaseReservationResources>){const ReservationRef reservation=[&](){if constexpr(std::is_same_v<T,ReleaseActionResources>)return ReservationRef{op.action_id};else return op.reservation;}();for(const auto& row:policy.inventories.rows()){const auto* inv=c.inventory(row.first);if(!inv)return common_failure("ProtectedMarketInventoryMissing",row.first);for(const auto& lot:inv->lots)if(lot.reserved_by==reservation)return common_failure("ProtectedMarketReservationMutation",row.first);}return common_success();}
        else if constexpr(std::is_same_v<T,CreateInventory>)return policy.inventories.find(op.inventory.id)?common_failure("ProtectedMarketIdentityMutation",op.inventory.id):common_success();
        else if constexpr(std::is_same_v<T,MoveIntegrationLot>)return policy.inventories.find(op.source_id)||policy.inventories.find(op.destination_id)?common_failure("ProtectedMarketUnsupportedWriter"):common_success();
        else if constexpr(std::is_same_v<T,ReserveLots>||std::is_same_v<T,AdjustLots>||std::is_same_v<T,SetInventoryCapacity>||std::is_same_v<T,SetInventoryOwner>||std::is_same_v<T,SetLotOwner>)return policy.inventories.find(op.inventory_id)?common_failure("ProtectedMarketUnsupportedWriter",op.inventory_id):common_success();
        else return common_failure("ProtectedMarketUnknownOperation");
    },operation);if(!checked.ok)return {false,{},checked.error};}
    if(scope){if(actual.size()!=scope->expected_market_legs.size())return fail("ProtectedMarketScopeLegMismatch");for(std::size_t i=0;i<actual.size();++i)if(!leg_equal(actual[i],scope->expected_market_legs[i]))return fail("ProtectedMarketScopeLegMismatch",actual[i].inventory_id);}
    return {true,std::move(out),{}};
}
Outcome<MarketInventoryChange> capture_protected_market_inventory(const ProtectedMarketAccounts& policy,const MarketRecipeInventoryTouch& touch,const InventoryView& before,const InventoryView& after,Integer low,Integer high){
    auto fail=[](const StableId& code,const StableId& id=StableId{})->Outcome<MarketInventoryChange>{return {false,{},common_failure(code,id).error};};const auto* selected=policy.inventories.find(touch.inventory_id);
    if(!selected||before.id!=touch.inventory_id||after.id!=before.id||!owner_equal(before.owner,selected->owner)||!owner_equal(after.owner,selected->owner)||before.capacity!=selected->capacity||after.capacity!=before.capacity||!same_order(before.field_order,after.field_order,{"id","owner","capacity","revision","lots"})||before.revision<0||after.revision<before.revision||low<1||high<low||touch.legs.empty())return fail("ProtectedMarketCaptureBoundaryInvalid",touch.inventory_id);
    std::map<StableId,const LotView*> old,next;for(const auto& lot:before.lots)if(lot.quantity<=0||lot.extra||lot.owner.extra||!owner_equal(lot.owner,selected->owner)||!lot.reserved_by.empty()||!old.emplace(lot.id,&lot).second)return fail("ProtectedMarketInitialLotInvalid",lot.id);for(const auto& lot:after.lots)if(lot.quantity<=0||lot.extra||lot.owner.extra||!owner_equal(lot.owner,selected->owner)||!lot.reserved_by.empty()||!next.emplace(lot.id,&lot).second)return fail("ProtectedMarketFinalLotInvalid",lot.id);
    MarketInventoryChange out;out.inventory_id=before.id;out.revision_before=before.revision;out.revision_after=after.revision;std::map<std::pair<StableId,bool>,Integer> actual,expected;Integer added=0;
    auto accumulate=[&](const StableId& item,bool positive,Integer q){auto& amount=actual[{item,positive}];if(q<0||q>INT64_MAX-amount)return false;amount+=q;return true;};
    for(const auto& lot:before.lots){auto at=next.find(lot.id);if(at==next.end()){out.lots.push_back({lot.id,lot,{}});if(!accumulate(lot.item_id,false,lot.quantity))return fail("ProtectedMarketQuantityOverflow");continue;}const auto& value=*at->second;if(!metadata_equal(lot,value)||value.quantity>lot.quantity)return fail("ProtectedMarketExistingLotMutation",lot.id);if(value.quantity<lot.quantity){out.lots.push_back({lot.id,lot,value});if(!accumulate(lot.item_id,false,lot.quantity-value.quantity))return fail("ProtectedMarketQuantityOverflow");}}
    std::vector<StableId> kept_before,kept_after;for(const auto& lot:before.lots)if(next.count(lot.id))kept_before.push_back(lot.id);bool seen_new=false;
    for(const auto& lot:after.lots){if(old.count(lot.id)){if(seen_new)return fail("ProtectedMarketLotOrderChanged",lot.id);kept_after.push_back(lot.id);continue;}seen_new=true;auto id=lot_ordinal(lot.id);if(!id.ok||id.value<low||id.value>=high||!same_order(lot.field_order,{}, {"id","item_id","quantity","owner","reserved_by"}))return fail("ProtectedMarketNewLotIdentityInvalid",lot.id);out.lots.push_back({lot.id,{},lot});if(!accumulate(lot.item_id,true,lot.quantity))return fail("ProtectedMarketQuantityOverflow");++added;}
    if(kept_before!=kept_after)return fail("ProtectedMarketLotOrderChanged",before.id);
    // 原ConsumeLots/TransferLots从库存原批次顺序扣除；同总量不能换扣另一批历史货物。
    auto fifo=before;for(const auto& leg:touch.legs)if(leg.signed_quantity<0){if(leg.signed_quantity==INT64_MIN)return fail("ProtectedMarketQuantityOverflow");Integer remaining=-leg.signed_quantity;for(auto& lot:fifo.lots)if(lot.item_id==leg.item_id&&owner_equal(lot.owner,leg.owner)&&lot.reserved_by.empty()){const auto used=std::min(remaining,lot.quantity);lot.quantity-=used;remaining-=used;if(!remaining)break;}if(remaining)return fail("ProtectedMarketFifoSourceInsufficient",before.id);}
    for(const auto& lot:fifo.lots){const auto at=next.find(lot.id);if((lot.quantity==0&&at!=next.end())||(lot.quantity>0&&(at==next.end()||at->second->quantity!=lot.quantity)))return fail("ProtectedMarketFifoMismatch",lot.id);}

    for(const auto& leg:touch.legs){if(leg.inventory_id!=before.id||!owner_equal(leg.owner,selected->owner)||leg.signed_quantity==0||leg.signed_quantity==INT64_MIN)return fail("ProtectedMarketScopeLegMismatch",before.id);auto& amount=expected[{leg.item_id,leg.signed_quantity>0}];const auto q=leg.signed_quantity>0?leg.signed_quantity:-leg.signed_quantity;if(q>INT64_MAX-amount)return fail("ProtectedMarketQuantityOverflow");amount+=q;}
    if(actual!=expected||touch.consume_operations<0||touch.add_operations<0||added<touch.add_operations||(!touch.fragmented_adds&&added!=touch.add_operations)||after.revision-before.revision!=touch.consume_operations+added||out.lots.empty())return fail("ProtectedMarketCapturedDeltaMismatch",before.id);
    return {true,std::move(out),{}};
}
}
